import json, sys, re

errors = []

for fname in ["output/tc/tc-F01.json", "output/tc/tc-F02.json"]:
    try:
        with open(fname, "r", encoding="utf-8") as f:
            data = json.load(f)
    except json.JSONDecodeError as e:
        errors.append(f"{fname}: JSON解析失败 - {e}")
        continue

    name = data.get("name", "")
    headers = data.get("headers", [])
    rows = data.get("rows", [])

    # 检查name格式
    if not re.match(r"^F\d+-TC$", name):
        errors.append(f"{fname}: name格式不合规: {name}")

    # 检查headers
    expected_headers = ["AI用例编号", "系统", "系统功能", "测试点", "用例名称", "优先级", "用例类型", "测试方法", "前置条件", "测试数据", "测试步骤", "预期结果", "依据类型", "备注", "需求分组名称", "需求名称", "是否可入库", "是否删除"]
    if headers != expected_headers:
        errors.append(f"{fname}: headers不匹配预期")

    # 检查每行
    valid_priorities = {"高", "中", "低"}
    valid_types = {"流程用例", "功能用例"}
    valid_methods = {"等价类+边界值", "决策表", "状态迁移", "场景法", "正交实验", "错误推测"}
    valid_evidence = {"原文依据", "补充条目"}
    # 澄清依据格式: 澄清依据(C-XX)

    tc_numbers = []
    for i, row in enumerate(rows):
        row_num = i + 1
        if len(row) != len(headers):
            errors.append(f"{fname}: 第{row_num}行字段数不等于headers数 ({len(row)} vs {len(headers)})")
            continue

        tc_id = row[0]
        # AI用例编号 TC-\d+
        if not re.match(r"^TC-\d+$", tc_id):
            errors.append(f"{fname}: 第{row_num}行 AI用例编号格式不合规: {tc_id}")
        tc_numbers.append(tc_id)

        # 系统
        if not row[1]:
            errors.append(f"{fname}: 第{row_num}行 系统为空")

        # 系统功能
        if not row[2]:
            errors.append(f"{fname}: 第{row_num}行 系统功能为空")

        # 测试点: TP-编号 测试点名
        if not re.match(r"^TP-\d+ .+", row[3]):
            errors.append(f"{fname}: 第{row_num}行 测试点格式不合规: {row[3][:50]}")

        # 优先级
        if row[5] not in valid_priorities:
            errors.append(f"{fname}: 第{row_num}行 优先级不在枚举内: {row[5]}")

        # 用例类型
        if row[6] not in valid_types:
            errors.append(f"{fname}: 第{row_num}行 用例类型不在枚举内: {row[6]}")

        # 测试方法
        if row[7] not in valid_methods:
            errors.append(f"{fname}: 第{row_num}行 测试方法不在枚举内: {row[7]}")

        # 前置条件
        if not row[8]:
            errors.append(f"{fname}: 第{row_num}行 前置条件为空")

        # 测试数据
        if not row[9]:
            errors.append(f"{fname}: 第{row_num}行 测试数据为空")

        # 测试步骤 - 必须是数组
        if not isinstance(row[10], list):
            errors.append(f"{fname}: 第{row_num}行 测试步骤不是数组: {type(row[10])}")
        elif len(row[10]) == 0:
            errors.append(f"{fname}: 第{row_num}行 测试步骤为空数组")

        # 预期结果
        if not row[11]:
            errors.append(f"{fname}: 第{row_num}行 预期结果为空")

        # 依据类型
        ev = row[12]
        if ev in valid_evidence:
            pass
        elif re.match(r"^澄清依据\(C-\d+\)$", ev):
            pass
        else:
            errors.append(f"{fname}: 第{row_num}行 依据类型不合规: {ev}")

        # 备注 - 必须是数组
        if not isinstance(row[13], list):
            errors.append(f"{fname}: 第{row_num}行 备注不是数组: {type(row[13])}")
        elif len(row[13]) == 0:
            errors.append(f"{fname}: 第{row_num}行 备注为空数组")

        # 是否可入库
        if row[15] not in {"是", "否"}:
            errors.append(f"{fname}: 第{row_num}行 是否可入库不在枚举内: {row[15]}")

        # 是否删除
        if row[16] not in {"是", "否"}:
            errors.append(f"{fname}: 第{row_num}行 是否删除不在枚举内: {row[16]}")

    # 检查编号唯一性
    seen = set()
    for tc_id in tc_numbers:
        if tc_id in seen:
            errors.append(f"{fname}: AI用例编号重复: {tc_id}")
        seen.add(tc_id)

    # 检查编号连续性（从TC-001开始递增）
    expected_num = 1
    for tc_id in tc_numbers:
        actual_num = int(tc_id.split("-")[1])
        if actual_num != expected_num:
            errors.append(f"{fname}: 编号不连续，期望TC-{expected_num:03d}，实际{tc_id}")
        expected_num += 1

    print(f"{fname}: 共 {len(rows)} 条TC")

# 检查TP编号在对应TP文件中存在
for tc_file, tp_file in [("output/tc/tc-F01.json", "output/tp/tp-F01.json"), ("output/tc/tc-F02.json", "output/tp/tp-F02.json")]:
    with open(tc_file, "r", encoding="utf-8") as f:
        tc_data = json.load(f)
    with open(tp_file, "r", encoding="utf-8") as f:
        tp_data = json.load(f)
    tp_ids = set(row[0] for row in tp_data["rows"])
    tp_names = {row[0]: row[2] for row in tp_data["rows"]}
    tc_tp_refs = set()
    for row in tc_data["rows"]:
        tp_ref = row[3]
        tp_id = tp_ref.split(" ")[0]
        tp_name_part = tp_ref[len(tp_id)+1:]
        tc_tp_refs.add(tp_id)
        if tp_id not in tp_ids:
            errors.append(f"{tc_file}: 引用不存在的TP编号: {tp_id}")
        elif tp_name_part != tp_names.get(tp_id, ""):
            errors.append(f"{tc_file}: TP名称不匹配，TC引用\"{tp_name_part[:40]}\" vs TP文件\"{tp_names.get(tp_id, \"\")[:40]}\"")
    print(f"{tc_file}: 引用TP编号集合 = {sorted(tc_tp_refs)}")

# 检查同一TP内用例名称不重名
for tc_file in ["output/tc/tc-F01.json", "output/tc/tc-F02.json"]:
    with open(tc_file, "r", encoding="utf-8") as f:
        tc_data = json.load(f)
    tp_titles = {}
    for row in tc_data["rows"]:
        tp_id = row[3].split(" ")[0]
        title = row[4]
        key = (tp_id, title)
        if key in tp_titles:
            errors.append(f"{tc_file}: 同一TP内用例名称重名: TP={tp_id}, 标题={title}")
        tp_titles[key] = True

# 检查字符串字段无真实换行
for tc_file in ["output/tc/tc-F01.json", "output/tc/tc-F02.json"]:
    with open(tc_file, "r", encoding="utf-8") as f:
        tc_data = json.load(f)
    for i, row in enumerate(tc_data["rows"]):
        for j, val in enumerate(row):
            if isinstance(val, str) and "\n" in val:
                errors.append(f"{tc_file}: 第{i+1}行第{j}列字符串含真实换行符")

# 检查澄清依据的C编号在澄清台账存在
valid_c_ids = {"C-01","C-02","C-03","C-04","C-05","C-06","C-07","C-08","C-09","C-10","C-11"}
for tc_file in ["output/tc/tc-F01.json", "output/tc/tc-F02.json"]:
    with open(tc_file, "r", encoding="utf-8") as f:
        tc_data = json.load(f)
    for row in tc_data["rows"]:
        ev = row[12]
        m = re.match(r"^澄清依据\((C-\d+)\)$", ev)
        if m:
            c_id = m.group(1)
            if c_id not in valid_c_ids:
                errors.append(f"{tc_file}: 澄清台账不存在的C编号: {c_id}")

# 检查系统功能逐字等于TP文件的系统功能
for tc_file, tp_file in [("output/tc/tc-F01.json", "output/tp/tp-F01.json"), ("output/tc/tc-F02.json", "output/tp/tp-F02.json")]:
    with open(tc_file, "r", encoding="utf-8") as f:
        tc_data = json.load(f)
    with open(tp_file, "r", encoding="utf-8") as f:
        tp_data = json.load(f)
    tp_sys_funcs = set(row[1] for row in tp_data["rows"])
    for row in tc_data["rows"]:
        if row[2] not in tp_sys_funcs:
            errors.append(f"{tc_file}: 系统功能不等于TP文件中的值: {row[2]}")

# 检查需求分组名称和需求名称为空字符串（briefing中未提供）
for tc_file in ["output/tc/tc-F01.json", "output/tc/tc-F02.json"]:
    with open(tc_file, "r", encoding="utf-8") as f:
        tc_data = json.load(f)
    for i, row in enumerate(tc_data["rows"]):
        if row[14] != "":
            errors.append(f"{tc_file}: 第{i+1}行 需求分组名称应为空字符串")
        if row[15] != "" and row[15] not in {"是","否"}:
            errors.append(f"{tc_file}: 第{i+1}行 需求名称字段位置可能错误")

if errors:
    print("\n=== 机验失败 ===")
    for e in errors:
        print(f"  - {e}")
    sys.exit(1)
else:
    print("\n=== 机验通过 ===")
    print(f"F01-TC: {len(json.load(open(\"output/tc/tc-F01.json\"))[\"rows\"])} 条")
    print(f"F02-TC: {len(json.load(open(\"output/tc/tc-F02.json\"))[\"rows\"])} 条")
