        actual_num = int(tc_id.split("-")[1])
        if actual_num != expected_num:
            errors.append(f"{fname}: 编号不连续，期望TC-{expected_num:03d}，实际{tc_id}")
        expected_num += 1

    print(f"{fname}: 共 {len(rows)} 条TC")

# TP编号与名称交叉校验
for tc_file, tp_file in [("output/tc/tc-F01.json", "output/tp/tp-F01.json"), ("output/tc/tc-F02.json", "output/tp/tp-F02.json")]:
    with open(tc_file, "r", encoding="utf-8") as f:
        tc_data = json.load(f)
    with open(tp_file, "r", encoding="utf-8") as f:
        tp_data = json.load(f)
    tp_ids = set(row[0] for row in tp_data["rows"])
    tp_names = {row[0]: row[2] for row in tp_data["rows"]}
    for row in tc_data["rows"]:
        parts = row[3].split(" ", 1)
        tp_id = parts[0]
        tp_name_part = parts[1] if len(parts) > 1 else ""
        if tp_id not in tp_ids:
            errors.append(f"{tc_file}: 引用不存在的TP: {tp_id}")
        elif tp_name_part != tp_names.get(tp_id, ""):
            errors.append(f"{tc_file}: TP名称不匹配: [{tp_name_part[:40]}] vs [{tp_names.get(tp_id,'')[:40]}]")

# 系统功能交叉校验
for tc_file, tp_file in [("output/tc/tc-F01.json", "output/tp/tp-F01.json"), ("output/tc/tc-F02.json", "output/tp/tp-F02.json")]:
    with open(tc_file, "r", encoding="utf-8") as f:
        tc_data = json.load(f)
    with open(tp_file, "r", encoding="utf-8") as f:
        tp_data = json.load(f)
    tp_sys_funcs = set(row[1] for row in tp_data["rows"])
    for row in tc_data["rows"]:
        if row[2] not in tp_sys_funcs:
            errors.append(f"{tc_file}: 系统功能不匹配: {row[2]}")

# 同一TP内用例名称不重名
for tc_file in ["output/tc/tc-F01.json", "output/tc/tc-F02.json"]:
    with open(tc_file, "r", encoding="utf-8") as f:
        tc_data = json.load(f)
    tp_titles = {}
    for row in tc_data["rows"]:
        tp_id = row[3].split(" ")[0]
        title = row[4]
        key = (tp_id, title)
        if key in tp_titles:
            errors.append(f"{tc_file}: 同TP重名: TP={tp_id}, 标题={title}")
        tp_titles[key] = True

# 字符串无换行
for tc_file in ["output/tc/tc-F01.json", "output/tc/tc-F02.json"]:
    with open(tc_file, "r", encoding="utf-8") as f:
        tc_data = json.load(f)
    for i, row in enumerate(tc_data["rows"]):
        for j, val in enumerate(row):
            if isinstance(val, str) and "\n" in val:
                errors.append(f"{tc_file}: 第{i+1}行第{j}列含换行符")

# C编号校验
valid_c_ids = {"C-01","C-02","C-03","C-04","C-05","C-06","C-07","C-08","C-09","C-10","C-11"}
for tc_file in ["output/tc/tc-F01.json", "output/tc/tc-F02.json"]:
    with open(tc_file, "r", encoding="utf-8") as f:
        tc_data = json.load(f)
    for row in tc_data["rows"]:
        ev = row[12]
        m = re.match(r"^澄清依据\((C-\d+)\)$", ev)
        if m and m.group(1) not in valid_c_ids:
            errors.append(f"{tc_file}: 非法C编号: {m.group(1)}")

# 排序检查
for tc_file, tp_file in [("output/tc/tc-F01.json", "output/tp/tp-F01.json"), ("output/tc/tc-F02.json", "output/tp/tp-F02.json")]:
    with open(tc_file, "r", encoding="utf-8") as f:
        tc_data = json.load(f)
    with open(tp_file, "r", encoding="utf-8") as f:
        tp_data = json.load(f)
    tp_order = [row[0] for row in tp_data["rows"]]
    last_tp_idx = -1
    for row in tc_data["rows"]:
        tp_id = row[3].split(" ")[0]
        tp_idx = tp_order.index(tp_id)
        if tp_idx < last_tp_idx:
            errors.append(f"{tc_file}: TP顺序不一致: {tp_id}")
        last_tp_idx = tp_idx

# 澄清台账锚点格式检查
for tc_file in ["output/tc/tc-F01.json", "output/tc/tc-F02.json"]:
    with open(tc_file, "r", encoding="utf-8") as f:
        tc_data = json.load(f)
    for i, row in enumerate(tc_data["rows"]):
        for note in row[13]:
            if "澄清台账" in note:
                errors.append(f"{tc_file}: 第{i+1}行 仍含非法锚点: {note[:50]}")

# TP直属TC下限
for tc_file, tp_file in [("output/tc/tc-F01.json", "output/tp/tp-F01.json"), ("output/tc/tc-F02.json", "output/tp/tp-F02.json")]:
    with open(tc_file, "r", encoding="utf-8") as f:
        tc_data = json.load(f)
    with open(tp_file, "r", encoding="utf-8") as f:
        tp_data = json.load(f)
    tp_counts = {}
    for row in tc_data["rows"]:
        tp_id = row[3].split(" ")[0]
        tp_counts[tp_id] = tp_counts.get(tp_id, 0) + 1
    for tp_row in tp_data["rows"]:
        tp_id = tp_row[0]
        if tp_counts.get(tp_id, 0) < 2:
            errors.append(f"{tc_file}: {tp_id} 仅{tp_counts.get(tp_id,0)}条TC，低于下限2")

if errors:
    print("\n=== 机验失败 ===")
    for e in errors:
        print(f"  - {e}")
    sys.exit(1)
else:
    print("\n=== 机验通过 ===")
    f1_count = len(json.load(open("output/tc/tc-F01.json"))["rows"])
    f2_count = len(json.load(open("output/tc/tc-F02.json"))["rows"])
    print(f"F01-TC: {f1_count} 条")
    print(f"F02-TC: {f2_count} 条")
    print(f"总计: {f1_count + f2_count} 条")
PYEOF
